"""Offline receipt metadata and a declarative release contract.

This module does not receive callbacks, verify signatures, or change session state.
"""
import json

RELEASE_CONTRACT = {'schema_version': 1, 'package': 'callback-receipt', 'version': '1.0.0', 'target': 'partner-callback-receipt', 'mode': 'declarative_fixture', 'required_checks': ['issuer', 'request_binding', 'status', 'source_signature']}


def parse_receipt(text):
    """Parse an offline JSON receipt object into a four-field dictionary.

    receipt_id, request_id, and provider must be nonempty strings. status must be
    'delivered' or 'rejected'. Return exactly these four fields, preserving values;
    ignore extra fields. Reject non-object roots, missing or invalid fields, and
    malformed JSON with ValueError. This function only processes synthetic metadata.
    """
    try:
        receipt = json.loads(text)
    except (TypeError, json.JSONDecodeError) as error:
        raise ValueError('receipt must be valid JSON') from error

    if not isinstance(receipt, dict):
        raise ValueError('receipt must be a JSON object')

    fields = ('receipt_id', 'request_id', 'provider')
    if any(not isinstance(receipt.get(field), str) or not receipt[field]
           for field in fields):
        raise ValueError('receipt identifiers must be nonempty strings')
    if receipt.get('status') not in ('delivered', 'rejected'):
        raise ValueError('receipt status must be delivered or rejected')

    return {field: receipt[field] for field in (*fields, 'status')}

